INSERT INTO `skill_table` (`num`, `name`, `inclusive`, `series`, `explain`, `money`, `skillable`) VALUES (36,'Digging                        ',12,1,'用锄头将找到的药草挖出来，药草虽然很难找到，但卖的价钱很高                                          ',100,0),(37,'Makepowder                     ',12,1,'将挖出来的药草加工成粉末，要制作药水将需要药草粉，所以价格比药草贵                                  ',100,0),(38,'Herding                        ',13,1,'让大规模的家畜移动 可以带家畜到其它的村庄去或卖掉                                                   ',100,0),(39,'Milking                        ',13,1,'可以从牛身上挤出牛奶的技能                                                                          ',100,10),(40,'Midwifery                      ',13,1,'x                                                                                                   ',100,30),(41,'Shear                          ',13,1,'剪羊毛的技能                                                                                        ',100,30),(42,'Manufacturing                  ',14,1,'用这个技能可以做出大部份与木头相关物品，武器与相关物品有很多都是用这个技能做出来的                  ',100,0),(43,'Manufacturing                  ',15,1,'用这个技能可以做出大部份与铁有关的物品，剑与盾牌等都是用这个技能做出来的                            ',100,0),(44,'Cooking                        ',16,1,'可以做出所有菜肴类的物品，由于可以提升体力，所以战斗或用到技能时需经常使用                          ',100,0),(45,'Clothing                       ',17,1,'织出布来作为制作衣服的材料                                                                          ',100,0),(46,'Dyeing                         ',17,1,'可更换创角色的时候所决定的带子的颜色及做衣服的能力                                                  ',100,0),(47,'Tailoring                      ',17,1,'可以用布做成衣服，或用兽皮做成甲衣                                                                  ',100,0),(48,'Bowcrafting                    ',18,1,'可以用木头和线做成弓                                                                                ',100,0),(49,'Fletching                      ',18,1,'可以用木头和箭头做成箭                                                                              ',100,0),(85,'Appraisal                      ',30,3,'可知道戒指或项链物品的状态和效能                                                                    ',100,0),(86,'Healing                        ',31,3,'治疗较轻的伤口，使生命值稍微上升的能力，较魔法治疗的效果低                                          ',100,0),(87,'Tactics                        ',32,3,'利用羊毛来做毛线的能力                                                                              ',100,0),(88,'Crapple                        ',32,3,'x                                                                                                   ',100,0),(89,'Swordmanship                   ',32,3,'x                                                                                                   ',100,0),(90,'Archery                        ',32,3,'x                                                                                                   ',100,0),(91,'Fencing                        ',32,3,'x                                                                                                   ',100,0),(92,'Mace Fighting                  ',32,3,'x                                                                                                   ',100,0),(93,'Pierce                         ',32,3,'x                                                                                                   ',100,0),(94,'Whirl                          ',32,3,'x                                                                                                   ',100,0),(95,'Hurl                           ',32,3,'x                                                                                                   ',100,0),(96,'Parrying                       ',32,3,'x                                                                                                   ',100,0),(97,'Double Swordmanship            ',32,3,'x                                                                                                   ',100,0),(98,'Double Macefighting            ',32,3,'x                                                                                                   ',100,0),(1,'Detect Ghost                   ',0,0,'只有祭司可以用，能看到死去玩家的幽灵，如果同伴死在洞窟之中，可以用此项技能找到                      ',100,0),(2,'Talk With Ghost                ',0,0,'可以和幽灵对话的能力，如果有四处飘游的幽灵，用此项技能可以听见他们说的话，可以迅速找到死去的同伴幽灵',100,0),(3,'Poisoning                      ',1,0,'把毒沾在武器上或混入食物中让对方中毒，若用此有毒的武器攻击的话，对方中毒的机率会上升                ',100,0),(4,'Detect Poison                  ',1,0,'确认物品上是否沾上毒的能力，使用此技术就可确认物品是否有毒                                          ',100,0),(5,'Find Traps                     ',2,0,'可以找到埋在地底的陷阱，若有人使用设置陷阱技能在周围设置了陷阱，可用此技能找出陷阱                  ',100,0),(6,'Remove Traps                   ',2,0,'找出陷阱后可以用此技能解除陷阱，若成功解除陷阱，可得到一个陷阱物品                                  ',100,0),(7,'Entrapment                     ',2,0,'可以陷阱物品在地上设置陷阱，可带给未发现陷阱的玩家与怪物伤害                                        ',100,0),(8,'Magic Scrolling                ',3,0,'可将自己的魔法做成滚动条，让其它不具该魔法能力或未记忆该魔法的玩家，也可使用这个魔法                ',100,0),(9,'Ability Scrolling              ',3,0,'可制作能让各种技能的能力值上升的滚动条                                                              ',100,0),(10,'Emergency Alram                ',4,0,'会感知到周围是否有罪犯或拥有危险价值观的人，但是却无法正确知道那个人到底是谁                        ',100,0),(11,'First Aid                      ',4,0,'在危急的瞬间提升对象若干的生命值，是和治疗(Healing)相似的技术，但是只有对象的生命值，在一定数值以下?',100,0),(12,'Fast Foot                      ',4,0,'在较短的时间内让角色的移动速度增加，是在遭遇较强的怪物或敌人时才能施展的技术                        ',100,0),(13,'Secrethear                     ',4,0,'可以看到无法进入的建筑物的内部状况，建筑物内有谁躲在里面，或说什么话都可听到                        ',100,0),(14,'Wallclimbing                   ',4,0,'x                                                                                                   ',100,0),(15,'Intuition                      ',4,0,'使用此项技术可知道对方的等级，若知道对方等级，战斗时可以推测对方的战斗力                            ',100,0),(16,'Detect Bomb                    ',5,0,'可用来寻找设置在箱子上的炸弹，找到炸弹后可点选移除炸弹技能来移除炸弹                                ',100,0),(17,'Bomb in Box                    ',5,0,'可将炸弹设置在箱子内，若其它的使用者不慎打开箱子会受到伤害                                          ',100,0),(18,'Remove Bomb                    ',5,0,'移除炸弹后可安全地打开箱子，若打开了设置炸弹的箱子就会受到伤害                                      ',100,0),(19,'Stealing                       ',6,0,'可从其它人物的背包中偷走一个物品，但此技能会导致价值观恶化                                          ',100,0),(20,'Lockpicking                    ',6,0,'可以打开锁上的门或箱子                                                                              ',100,0),(21,'Reclaim                        ',7,1,'开垦土地的能力                                                                                      ',100,0),(22,'Sow                            ',7,1,'将植物种子播在开垦好的土地上                                                                        ',100,0),(23,'Cultivate                      ',7,1,'撒种耕作并使作物成长的技术                                                                          ',100,0),(24,'Havest                         ',7,1,'将长成的植物收割的能力                                                                              ',100,0),(25,'Detect Mineral                 ',8,1,'找出隐藏在地底矿物的能力，在开采前必须先找到矿脉，通常在岩石附近                                    ',100,0),(26,'Mining                         ',8,1,'利用十字镐将已经探勘出来的矿脉中将矿石开采出来                                                      ',100,0),(27,'Refine                         ',8,1,'可以将开采出来的矿石制炼成块，提炼出来的块的价钱比矿石高                                            ',100,0),(28,'Fish - Hooking                 ',9,1,'可以在河边或海边利用钓竿来钓鱼，缺点是能够使用此技能的地点很有限                                    ',100,0),(29,'Baitmaking                     ',9,1,'用其它的物品制作成钓鱼时用的鱼饵，会做鱼饵的话钓鱼的成功率会上升                                    ',100,20),(30,'Netting                        ',9,1,'可以在河边或海边利用渔网来捕鱼，缺点是能够使用此技能的地点很有限                                    ',100,30),(31,'Sailing                        ',9,1,'可驾船移动的能力                                                                                    ',100,50),(32,'Cutting                        ',10,1,'用斧头来砍树                                                                                        ',100,0),(33,'Lumbering                      ',10,1,'用锯子把原木锯成木材                                                                                ',100,0),(34,'Butchering                     ',11,1,'可以从死去的动物或怪物身上取得肉和皮，肉可以用来烹饪，皮可以做成皮甲衣                              ',100,0),(35,'Detect Herb                    ',12,1,'可以在树林中或原野上寻找药草，药草不会生长在特定的位置，所以要找很困难                              ',100,0),(99,'Magery                         ',32,3,'x                                                                                                   ',100,0),(100,'Orison                         ',32,3,'x                                                                                                   ',100,0),(101,'Thread                         ',17,1,'x                                                                                                   ',100,0),(102,'Coloring                       ',17,1,'可调整衣服的颜色                                                                                    ',100,0),(103,'Jump                           ',38,3,'可以跳跃来移动                                                                                      ',100,0),(104,'Riding                         ',39,3,'可容易的骑马 若骑马的话可以更快的速度移动                                                           ',100,0),(105,'Ghost Resurrection             ',0,0,'此技能可以让幽灵复活，可以立刻将死亡的同伴救活，若祭司在身边，就不需要为了复活大老远跑回村子里艾德布',100,0),(106,'GM Carpenter                   ',38,1,'可提升与木匠有关的稀有物品的技术                                                                    ',100,0),(107,'GM Blacksmith                  ',39,1,'可提升与铁匠有关的稀有物品的技术                                                                    ',100,0),(108,'GM Cook                        ',40,1,'可提升与厨师有关的稀有物品的技术                                                                    ',100,0),(109,'GM Tailor                      ',41,1,'可提升与裁缝师有关的稀有物品的技术                                                                  ',100,0),(110,'GM Bowcraft                    ',42,1,'可提升与制弓箭者有关的稀有物品的技术                                                                ',100,0),(111,'GM Alchemist                   ',43,1,'可提升与炼金术士有关的稀有物品的技术                                                                ',100,0),(112,'GM Candlemaker                 ',44,1,'可提升与制蜡匠有关的稀有物品的技术                                                                  ',100,0),(50,'MakePotion                     ',19,1,'利用药草粉可以制作各式各样的药剂                                                                    ',100,0),(51,'MakeMetal                      ',19,1,'使用各种金属制作合金                                                                                ',100,40),(52,'MakeBottle                     ',19,1,'可以制作用玻璃做的空瓶与空杯                                                                        ',100,0),(53,'Candlemaking                   ',20,1,'将加工过的蜂蜡做成蜡烛                                                                              ',100,0),(54,'Oiling                         ',20,1,'制作蜡烛的材料(蜡油)的能力                                                                          ',100,0),(55,'Repairng                       ',21,1,'增加物品的耐久度，使磨损度减少的技术                                                                ',100,0),(56,'Reutilizing                    ',22,1,'让磨损的物品或做错的物品变成材料再次使用的技术                                                      ',100,0),(57,'Playing                        ',23,2,'可使用笛子或喇叭等乐器演奏的技术，只单纯地演奏是没什么效果地                                        ',100,0),(58,'Peacemaking                    ',23,2,'演奏音乐让发怒的怪物或动物镇静下来可阻挡其攻击                                                      ',100,0),(59,'Paralysis                      ',23,2,'演奏音乐让怪物或动物暂时痲痹，发挥和痲痹术一样的效果                                                ',100,0),(60,'Hallucination                  ',23,2,'制造出幻象                                                                                          ',100,0),(61,'Provocation                    ',23,2,'欺骗攻击自己的怪物，使其互相争斗                                                                    ',100,0),(62,'Enticement                     ',23,2,'演奏音乐，暂时地迷惑 NPC                                                                            ',100,0),(63,'Noise                          ',23,2,'发出异常的声音，在周围制造噪音，给周围的人带来压力，或让 NPC 的攻击状态改变，并且影响名声值         ',100,0),(64,'Tracking                       ',24,2,'追踪足迹                                                                                            ',100,0),(65,'Snooping                       ',24,2,'从别人的背包后偷看背包内的物品                                                                      ',100,0),(66,'Search                         ',24,2,'可找出以物理性的方法隐藏的东西                                                                      ',100,0),(67,'Silentmove                     ',25,2,'以没有留下足迹和声音的方式移动                                                                      ',100,0),(68,'Disguise                       ',26,2,'使用伪装工具变成其它角色的样子或其它怪物的样子                                                      ',100,0),(69,'Chameleon                      ',26,2,'若不移动时，可用与背景相符合的颜色，将身体隐藏起来，即使在旁边的人也不知道，但移动力会减低 1/3      ',100,0),(70,'Hide on Tree                   ',26,2,'只在有树木的地方才能隐藏的技术                                                                      ',100,0),(71,'Object Hidding                 ',26,2,'放东西在盒子或箱子，以隐藏的方式移动箱子，也可施展盗贼的偷窃术，翻背包术                            ',100,0),(72,'Hide                           ',26,2,'只是单纯地隐藏而不移动                                                                              ',100,0),(73,'Camping                        ',27,2,'搭帐篷，可自由地进行休息和睡眠及注销，在旅行中为记忆魔法，此技能是必要的                            ',100,0),(74,'Makefire                       ',27,2,'可以在夜晚阻挡野生动物与怪物的袭击，另外，在野外烹饪时也一定要生火                                  ',100,0),(75,'Taming                         ',28,2,'可以驯服动物和怪物的技能，驯服后可以替他们取名字并用来保护驯服者                                    ',100,0),(76,'Communicate with Animal        ',29,2,'可以和动物对话的技能，若能听懂动物说的话，可以获取重要的情报                                        ',100,0),(77,'Communicate with Other Tribe   ',29,2,'可以和别的种族说话，若能听懂别的种族说的话，可以获取重要的情报                                      ',100,0),(78,'Animal lore                    ',30,3,'可以了解动物的状态，知道这个动物是否饥饿或生病等等，可以提升驯服动物的能力                          ',100,0),(79,'Arms lore                      ',30,3,'可以了解武器状态，可以看出掉在地上的武器状态以及隐藏的武器之效果                                    ',100,0),(80,'Evaluate Inteligence           ',30,3,'可以得知其它角色的智力值                                                                            ',100,0),(81,'Evaluate Wisdom                ',30,3,'可以得知其它角色的智能值                                                                            ',100,0),(82,'Anatomy Judgement              ',30,3,'可以看出死亡角色的死亡时的状况，能够知道死因及杀他的人                                              ',100,0),(83,'Item Identification            ',30,3,'可把握所有物品是否隐藏的能力 若有不知道的物品如魔法物品的情况  会将其能力告知                       ',100,0),(84,'Taste Identification           ',30,3,'可把握料理物品的味道 可知道料理的材料和是否有毒                                                     ',100,0);
