/*!50003 DROP PROCEDURE IF EXISTS `MailDelete` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=CURRENT_USER PROCEDURE `MailDelete`(IN p_index INT, IN p_receiver VARCHAR(20) CHARACTER SET utf8mb4)
BEGIN
    DECLARE v_vt INT DEFAULT NULL;
    DECLARE v_bodyidx INT DEFAULT NULL;
    SELECT ViewType INTO v_vt FROM maildata
    WHERE `INDEX` = p_index AND Receiver = p_receiver;
    IF v_vt = 0 THEN
        UPDATE maildata SET ViewType = 1
        WHERE `INDEX` = p_index AND Receiver = p_receiver;
    ELSEIF v_vt = 1 THEN
        SELECT BodyIndex INTO v_bodyidx FROM maildata
        WHERE `INDEX` = p_index AND Receiver = p_receiver;
        DELETE FROM maildata WHERE `INDEX` = p_index AND Receiver = p_receiver;
        IF v_bodyidx IS NOT NULL THEN
            IF NOT EXISTS (SELECT 1 FROM maildata WHERE BodyIndex = v_bodyidx) THEN
                DELETE FROM mailbody WHERE `INDEX` = v_bodyidx;
            END IF;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `MailGetBody` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=CURRENT_USER PROCEDURE `MailGetBody`(IN p_index INT, IN p_receiver VARCHAR(20) CHARACTER SET utf8mb4)
BEGIN
    DECLARE v_bodyidx INT DEFAULT NULL;
    SELECT BodyIndex INTO v_bodyidx FROM maildata
    WHERE `INDEX` = p_index AND Receiver = p_receiver;
    IF v_bodyidx IS NOT NULL AND v_bodyidx <> 0 THEN
        SELECT Body FROM mailbody WHERE `INDEX` = v_bodyidx;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `MailGetData` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=CURRENT_USER PROCEDURE `MailGetData`(IN p_index INT, IN p_receiver VARCHAR(20) CHARACTER SET utf8mb4)
BEGIN
    SELECT `INDEX`, Type, Sender, Receiver, Title, Date
    FROM maildata WHERE `INDEX` = p_index AND Receiver = p_receiver;
    UPDATE maildata SET IsRead = 1
    WHERE `INDEX` = p_index AND Receiver = p_receiver;
END ;;
