CREATE DEFINER=CURRENT_USER PROCEDURE `MailGetList`(IN p_receiver VARCHAR(20) CHARACTER SET utf8mb4, IN p_viewtype INT)
BEGIN
    SELECT `INDEX`, Type, IsRead, Sender, Receiver, Title, BodyIndex, Date
    FROM maildata
    WHERE Receiver = p_receiver AND ViewType = p_viewtype
    ORDER BY Date DESC
    LIMIT 60;
END ;;
