CREATE DEFINER=CURRENT_USER PROCEDURE `MailGetNotReadCount`(IN p_receiver VARCHAR(20) CHARACTER SET utf8mb4)
BEGIN
    UPDATE maildata SET ViewType = 1
    WHERE Receiver = p_receiver AND ViewType = 0
      AND Date > DATE_ADD(NOW(), INTERVAL 10 DAY);
    SELECT COUNT(`INDEX`) FROM maildata
    WHERE Receiver = p_receiver AND IsRead = 0 AND ViewType = 0;
END ;;
