CREATE DEFINER=CURRENT_USER PROCEDURE `MailInsert`(
    IN p_viewtype INT, IN p_type INT,
    IN p_sender VARCHAR(20) CHARACTER SET utf8mb4,
    IN p_receiver VARCHAR(20) CHARACTER SET utf8mb4,
    IN p_title VARCHAR(60) CHARACTER SET utf8mb4,
    IN p_body VARCHAR(1000) CHARACTER SET utf8mb4)
BEGIN
    DECLARE v_exist INT DEFAULT 0;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_bodyidx INT DEFAULT 0;
    SELECT COUNT(name) INTO v_exist FROM chr_info WHERE name = p_receiver;
    IF v_exist <> 0 THEN
        SELECT COUNT(*) INTO v_cnt FROM maildata
        WHERE Receiver = p_receiver AND (p_viewtype = 0);
        IF v_cnt <= 60 THEN
            INSERT INTO mailbody(Body) VALUES (p_body);
            SET v_bodyidx = LAST_INSERT_ID();
            INSERT INTO maildata(Type, ViewType, IsRead, Sender, Receiver, Date, Title, BodyIndex)
            VALUES (p_type, p_viewtype, 0, p_sender, p_receiver, NOW(), p_title, v_bodyidx);
        END IF;
    END IF;
END ;;
DELIMITER ;
