CREATE DEFINER=CURRENT_USER PROCEDURE `MailRepair`(IN p_index INT, IN p_receiver VARCHAR(20) CHARACTER SET utf8mb4)
BEGIN
    DECLARE v_vt INT DEFAULT NULL;
    SELECT ViewType INTO v_vt FROM maildata
    WHERE `INDEX` = p_index AND Receiver = p_receiver;
    IF v_vt = 1 THEN
        UPDATE maildata SET ViewType = 0
        WHERE `INDEX` = p_index AND Receiver = p_receiver;
    END IF;
END ;;
