CREATE DEFINER=CURRENT_USER PROCEDURE `MerchantBackupTakeUpdate`(
    IN p_no INT, IN p_isbuyer INT, IN p_value INT)
BEGIN
    UPDATE merchantbackup
    SET SellerTake = IF(p_isbuyer = 0, p_value, SellerTake),
        BuyerTake  = IF(p_isbuyer = 1, p_value, BuyerTake)
    WHERE `No` = p_no;
END ;;
