CREATE DEFINER=CURRENT_USER PROCEDURE `MerchantDelbyCancel`(
    IN p_no INT, IN p_name VARCHAR(20) CHARACTER SET utf8mb4, IN p_isend INT)
BEGIN
    INSERT INTO merchantbackup SELECT * FROM merchantseller
    WHERE `No` = p_no AND (SellerName = p_name OR BuyerName = p_name) AND IsEnd = p_isend;
    DELETE FROM merchantseller
    WHERE `No` = p_no AND (SellerName = p_name OR BuyerName = p_name) AND IsEnd = p_isend;
    SELECT ROW_COUNT() AS cnt;
END ;;
