CREATE DEFINER=CURRENT_USER PROCEDURE `MerchantItemBuyComform`(
    IN p_no INT, IN p_seller VARCHAR(20) CHARACTER SET utf8mb4,
    IN p_buyer VARCHAR(20) CHARACTER SET utf8mb4,
    IN p_setisend INT, IN p_beforeisend INT,
    IN p_itemno INT, IN p_attr1 INT, IN p_attr2 INT, IN p_attr3 INT,
    IN p_attr4 INT, IN p_attr5 INT, IN p_attr6 INT)
BEGIN
    UPDATE merchantseller
    SET IsEnd = p_setisend, BuyerName = p_buyer, EndDate = NOW()
    WHERE SellerName = p_seller AND `No` = p_no
      AND IsEnd = p_beforeisend AND SellerName <> p_buyer;
    SELECT `No`, SellerName, IsEnd, ExchangeMoney, SellItemNo,
           SellItemAttr1, SellItemAttr2, SellItemAttr3,
           SellItemAttr4, SellItemAttr5, SellItemAttr6
    FROM merchantseller
    WHERE `No` = p_no AND SellerName = p_seller AND IsEnd = p_setisend
      AND SellItemNo = p_itemno
      AND SellItemAttr1 = p_attr1 AND SellItemAttr2 = p_attr2
      AND SellItemAttr3 = p_attr3 AND SellItemAttr4 = p_attr4
      AND SellItemAttr5 = p_attr5 AND SellItemAttr6 = p_attr6;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
