CREATE DEFINER=CURRENT_USER PROCEDURE `MerchantItemSearch_Merchant_Day`(
    IN p_merchant VARCHAR(20) CHARACTER SET utf8mb4, IN p_day INT,
    IN p_isend INT, IN p_sellertake INT, IN p_buyertake INT, IN p_no INT)
BEGIN
    SELECT `No`, SellerName, BuyerName, IsEnd, SellerTake, BuyerTake, ExchangeMoney,
           SellItemNo, SellItemAttr1, SellItemAttr2, SellItemAttr3,
           SellItemAttr4, SellItemAttr5, SellItemAttr6
    FROM merchantseller
    WHERE SellerName = p_merchant AND IsEnd = p_isend
      AND DATEDIFF(NOW(), RegDate) < p_day
      AND SellerTake = p_sellertake AND BuyerTake = p_buyertake AND `No` > p_no
    ORDER BY `No` LIMIT 24;
END ;;
DELIMITER ;
