CREATE DEFINER=CURRENT_USER PROCEDURE `MerchantResultItemTakeBuyerSideComform`(
    IN p_no INT, IN p_name VARCHAR(20) CHARACTER SET utf8mb4,
    IN p_isend INT, IN p_buyertake INT, IN p_beforebuyertake INT)
BEGIN
    UPDATE merchantseller SET BuyerTake = p_buyertake
    WHERE BuyerName = p_name AND `No` = p_no
      AND IsEnd = p_isend AND BuyerTake = p_beforebuyertake;
    SELECT `No`, SellerName, BuyerName, SellerTake, BuyerTake, ExchangeMoney,
           SellItemNo, SellItemAttr1, SellItemAttr2, SellItemAttr3,
           SellItemAttr4, SellItemAttr5, SellItemAttr6
    FROM merchantseller
    WHERE `No` = p_no AND (SellerName = p_name OR BuyerName = p_name)
      AND IsEnd = p_isend AND BuyerTake = p_buyertake;
END ;;
