CREATE DEFINER=CURRENT_USER PROCEDURE `up_get_box_item_info`(IN p_pos VARCHAR(2), IN p_id INT)
BEGIN
    SET @zc_sql = CONCAT('SELECT item_', p_pos,
        ', attr_', p_pos, '_1, attr_', p_pos, '_2, attr_', p_pos, '_3',
        ', attr_', p_pos, '_4, attr_', p_pos, '_5, attr_', p_pos, '_6',
        ' FROM box_item WHERE id = ', p_id);
    PREPARE zc_stmt FROM @zc_sql;
    EXECUTE zc_stmt;
    DEALLOCATE PREPARE zc_stmt;
END ;;
DELIMITER ;
