/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=CURRENT_USER PROCEDURE `up_update_event_mapmove_now`(IN p_eventno INT, IN p_max INT, IN p_now INT)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_summit INT DEFAULT 0;
    SELECT COUNT(*), IFNULL(MAX(summit), 0) INTO v_cnt, v_summit
    FROM event_mapmove_now WHERE event_no = p_eventno;
    IF v_cnt > 0 THEN
        IF v_summit < p_now THEN
            UPDATE event_mapmove_now SET `max` = p_max, `now` = p_now, summit = p_now
            WHERE event_no = p_eventno;
        ELSE
            UPDATE event_mapmove_now SET `max` = p_max, `now` = p_now
            WHERE event_no = p_eventno;
        END IF;
    ELSE
        INSERT INTO event_mapmove_now (event_no, `max`, `now`, summit)
        VALUES (p_eventno, p_max, p_now, p_now);
    END IF;
END ;;
DELIMITER ;
